independent_column_maxima.candidate_sql:
SELECT order_id, MAX(symbol) AS symbol, MAX(side) AS side,
       MAX(open_qty) AS open_qty, MAX(limit_price_cents) AS limit_price_cents
FROM order_versions WHERE effective_at <= :effective_cutoff AND recorded_at <= :recorded_cutoff GROUP BY order_id;

